const qa3AdminToken = "qa3-admin-token"

// qa3Handler opens a fresh temp store and builds the composed handler
// independently of the coder's harness (own token, own status values).
func qa3Handler(t *testing.T) (http.Handler, *store.Store) {
	t.Helper()
	st, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "qa3.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	apiH := api.New(api.Deps{
		AdminToken: qa3AdminToken,
		Store:      st,
		Scan:       func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
		Status: func(context.Context) (api.AdminStatus, error) {
			return api.AdminStatus{
				Plugins: []api.PluginHealth{{ID: "base-scanner", State: "serving", Restarts: 0, CheckedAt: "2026-08-05T00:00:00Z"}},
				Enrich:  api.EnrichStats{Pending: 1, InFlight: 0, Done: 3, Failed: 0},
			}, nil
		},
	})
	return web.Handler(apiH, web.Options{}), st
}

func qa3Req(method, target, body string) *http.Request {
	r := httptest.NewRequest(method, target, bytes.NewReader([]byte(body)))
	r.Header.Set("Authorization", "Bearer "+qa3AdminToken)
	if body != "" {
		r.Header.Set("Content-Type", "application/json")
	}
	return r
}

// TestQA_LibraryWireKeySet_INV4 proves the library wire object exposes EXACTLY
// the INV4 key set on BOTH the create response and the list response — no
// store.Library internals (created_at and friends) leak across the boundary.
// A struct decode (the coder's approach) cannot catch a created_at leak;
// decoding into a map and diffing the key set can. The spec'd `description`
// field (web-ui-phase-3 task 1.2) is part of the wire contract and is
// expected; the invariant — no store persistence internals — still holds.
func TestQA_LibraryWireKeySet_INV4(t *testing.T) {
	h, _ := qa3Handler(t)
	wantKeys := map[string]bool{
		"id": true, "module_id": true, "root_path": true, "display_name": true,
		"description": true,
	}

	checkKeys := func(label string, obj map[string]any) {
		t.Helper()
		for k := range wantKeys {
			if _, ok := obj[k]; !ok {
				t.Errorf("%s: missing key %q (INV4)", label, k)
			}
		}
		for k := range obj {
			if !wantKeys[k] {
				t.Errorf("%s: unexpected key %q leaks across the boundary (INV4 breach — no store.Library/created_at over the wire)", label, k)
			}
		}
	}

	// Create response (POST /libraries) — the library object IS the top-level body.
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, qa3Req(http.MethodPost, "/api/v1/libraries", `{"module_id":"film","root_path":"/m/film","display_name":"Film"}`))
	if rec.Code != http.StatusCreated {
		t.Fatalf("create: status = %d, want 201 (body=%s)", rec.Code, rec.Body.String())
	}
	var created map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &created); err != nil {
		t.Fatalf("decode create body: %v (body=%s)", err, rec.Body.String())
	}
	checkKeys("POST /libraries response", created)

	// List response (GET /libraries) — the library object is items[0].
	rec = httptest.NewRecorder()
	h.ServeHTTP(rec, qa3Req(http.MethodGet, "/api/v1/libraries", ""))
	if rec.Code != http.StatusOK {
		t.Fatalf("list: status = %d, want 200", rec.Code)
	}
	var list struct {
		Items []map[string]any `json:"items"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &list); err != nil {
		t.Fatalf("decode list body: %v", err)
	}
	if len(list.Items) == 0 {
		t.Fatal("list items empty; expected the library just created")
	}
	checkKeys("GET /libraries items[0]", list.Items[0])
}

// TestQA_GetItemNotFoundCanonicalBody independently re-derives AC-4's 404 clause
// and asserts the FULL canonical body, including the retryable field the coder's
// test skips: retryable must be false for a not_found (permanent client error).
func TestQA_GetItemNotFoundCanonicalBody(t *testing.T) {
	h, _ := qa3Handler(t)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, qa3Req(http.MethodGet, "/api/v1/items/does-not-exist", ""))
	if rec.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want 404", rec.Code)
	}
	var body struct {
		Error struct {
			Code      string `json:"code"`
			Retryable bool   `json:"retryable"`
		} `json:"error"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode error body: %v", err)
	}
	if body.Error.Code != "not_found" {
		t.Errorf("error.code = %q, want not_found", body.Error.Code)
	}
	if body.Error.Retryable {
		t.Errorf("error.retryable = true, want false (not_found is permanent — must not be retried)")
	}
}
